CREATE FUNCTION public.garde_cas_pratique_feries() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE k text; n int; BEGIN IF NEW.exercice_id <> 'quiz_cas_pratique_feries_2026_v1' THEN RETURN NEW; END IF; IF TG_OP='UPDATE' AND OLD.completed IS TRUE AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'Quiz terminé : preuve conservée' USING ERRCODE='42501'; END IF; IF NEW.score IS NOT NULL OR NEW.reponses->>'version' IS DISTINCT FROM '2026-10-29-m12-feries-v1' OR jsonb_typeof(NEW.reponses->'valeurs') IS DISTINCT FROM 'object' OR coalesce(NEW.reponses->>'revision','')='' THEN RAISE EXCEPTION 'Identité de quiz invalide' USING ERRCODE='23514'; END IF; IF NEW.completed IS TRUE THEN FOR n IN 1..11 LOOP k := 'f'||lpad(n::text,2,'0'); IF jsonb_typeof(NEW.reponses->'valeurs'->k) IS DISTINCT FROM 'string' OR NEW.reponses->'valeurs'->>k !~ '^[0-2]$' THEN RAISE EXCEPTION 'Quiz jours fériés incomplet : %', k USING ERRCODE='23514'; END IF; END LOOP; END IF; RETURN NEW; END $$;
CREATE TRIGGER trg_garde_cas_pratique_feries BEFORE INSERT OR UPDATE ON public.reponses_apprenants FOR EACH ROW EXECUTE FUNCTION public.garde_cas_pratique_feries();
CREATE FUNCTION public.quiz_cas_pratique_feries_protection_prete() RETURNS boolean LANGUAGE sql STABLE SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM pg_trigger WHERE tgname='trg_garde_cas_pratique_feries' AND tgenabled='O'); $$;
GRANT EXECUTE ON FUNCTION public.quiz_cas_pratique_feries_protection_prete() TO authenticated, anon, service_role;